def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    seeds = [(int(y), int(x)) for y, x in zip(*np.where(g == 3))]

    def put(y, x, v):
        if 0 <= y < H and 0 <= x < W:
            out[y, x] = v

    # Stage 1: full-width colour-2 line two rows below each seed
    for r, c in seeds:
        if 0 <= r + 2 < H:
            out[r + 2, :] = 2
    emit(out, "Draw a full-width line of colour 2 two rows below each 3.")

    # Stage 2: stamp the gate motif around each seed
    for r, c in seeds:
        for dx in range(-2, 3):
            put(r - 2, c + dx, 5)   # top bar
            put(r + 2, c + dx, 8)   # floor bar over the 2-line
        put(r - 1, c, 5)            # stub pointing at the 3
        for dy in (-1, 0, 1):
            put(r + dy, c - 2, 2)   # side walls
            put(r + dy, c + 2, 2)
        put(r, c, 3)
        emit(out, f"Stamp the gate around the 3 at ({r},{c}): 5 roof with stub, 2 walls, 8 floor.")

    emit(out, "Final grid.")
    return out
